 /// Whether the post has been merged into another.\n  isMerged     Boolean           @default(false)\n  /// Target post id when this post was merged.\n  mergedIntoId String?\n  /// Submitting user id.\n  createdById  String\n  /// Submitting user relation.\n  createdBy    User              @relation(\"FeedbackPostAuthor\", fields: [createdById], references: [id], onDelete: Cascade)\n  /// Creation timestamp.\n  createdAt    DateTime          @default(now())\n  /// Last-updated timestamp.\n  updatedAt    DateTime          @updatedAt\n  /// Votes cast on this post.\n  votes        FeedbackVote[]\n  /// Comments on this post.\n  comments     FeedbackComment[]\n\n  @@index([status])\n  @@index([category])\n  @@index([agentSlug])\n  @@index([createdById])\n  @@index([voteCount])\n  @@index([createdAt])\n  @@map(\"feedback_post\")\n}\n\n/// A single upvote by a user on a FeedbackPost.\nmodel FeedbackVote {\n  /// Row id.\n  id         String       @id @default(cuid())\n  /// Voting user id.\n  userId     String\n  /// Voting user relation.\n  user       User         @relation(\"FeedbackVoteUser\", fields: [userId], references: [id], onDelete: Cascade)\n  /// Target post id.\n  feedbackId String\n  /// Target post relation.\n  feedback   FeedbackPost @relation(fields: [feedbackId], references: [id], onDelete: Cascade)\n  /// Vote timestamp.\n  createdAt  DateTime     @default(now())\n\n  @@unique([userId, feedbackId])\n  @@index([userId])\n  @@index([feedbackId])\n  @@map(\"feedback_vote\")\n}\n\n/// A comment left by a user (or admin) on a FeedbackPost.\nmodel FeedbackComment {\n  /// Row id.\n  id           String       @id @default(cuid())\n  /// Comment text.\n  content      String\n  /// Commenting user id.\n  userId       String\n  /// Commenting user relation.\n  user         User         @relation(\"FeedbackCommentUser\", fields: [userId], references: [id], onDelete: Cascade)\n  /// Parent post id.\n  feedbackId   String\n  /// Parent post relation.\n  feedback     FeedbackPost @relation(fields: [feedbackId], references: [id], onDelete: Cascade)\n  /// True when the comment was written by a platform admin.\n  isAdminReply Boolean      @default(false)\n  /// Creation timestamp.\n  createdAt    DateTime     @default(now())\n\n  @@index([feedbackId])\n  @@index([userId])\n  @@map(\"feedback_comment\")\n}\n\n/// A potential upcoming agent shown on the voting page.\nmodel UpcomingAgent {\n  /// Row id.\n  id          String              @id @default(cuid())\n  /// Display name of the proposed agent.\n  name        String\n  /// One-line tagline shown in the card.\n  tagline     String\n  /// Optional longer description.\n  description String?\n  /// Optional emoji avatar.\n  emoji       String?\n  /// Optional brand colour (hex or Tailwind name).\n  color       String?\n  /// Sort order for display.\n  order       Int                 @default(0)\n  /// Whether the card is visible to users.\n  isVisible   Boolean             @default(true)\n  /// Cached vote tally.\n  voteCount   Int                 @default(0)\n  /// Creation timestamp.\n  createdAt   DateTime            @default(now())\n  /// Last-updated timestamp.\n  updatedAt   DateTime            @updatedAt\n  /// Votes cast on this agent.\n  votes       UpcomingAgentVote[]\n\n  @@index([isVisible, order])\n  @@map(\"upcoming_agent\")\n}\n\n/// A single upvote by a user on an UpcomingAgent.\nmodel UpcomingAgentVote {\n  /// Row id.\n  id              String        @id @default(cuid())\n  /// Voting user id.\n  userId          String\n  /// Voting user relation.\n  user            User          @relation(\"UpcomingAgentVoteUser\", fields: [userId], references: [id], onDelete: Cascade)\n  /// Target agent id.\n  upcomingAgentId String\n  /// Target agent relation.\n  upcomingAgent   UpcomingAgent @relation(fields: [upcomingAgentId], references: [id], onDelete: Cascade)\n  /// Vote timestamp.\n  createdAt       DateTime      @default(now())\n\n  @@unique([userId, upcomingAgentId])\n  @@index([userId])\n  @@index([upcomingAgentId])\n  @@map(\"upcoming_agent_vote\")\n}\n\n/// Pre-launch waitlist entry collected before product launch.\nmodel WaitlistEntry {\n  id        String    @id @default(cuid())\n  email     String    @unique\n  coupon    String?\n  validTill DateTime?\n  createdAt DateTime  @default(now())\n\n  @@map(\"waitlist_entry\")\n}\n\n/// Scheduled task owned by an organization — agent-automated or user-defined.\nmodel Task {\n  /// Task id.\n  id             String       @id @default(cuid())\n  /// Owning organization id.\n  organizationId String\n  /// Owning organization relation.\n  organization   Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  /// Display name.\n  name           String\n  /// Optional description.\n  description    String?\n  /// Whether this is an automated agent task or a user-defined general task.\n  type           TaskType     @default(GENERAL)\n  /// Agent responsible for running this task (AGENT type only).\n  agent          Agent?\n  /// CRON expression for recurrence (null means one-off).\n  cronExpression String?\n  /// IANA timezone for the cron schedule.\n  timezone       String       @default(\"UTC\")\n  /// Whether the task is active and should run on schedule.\n  isEnabled      Boolean      @default(true)\n  /// True when seeded as a default task at org creation.\n  isDefault      Boolean      @default(false)\n  /// Extra configuration passed to the agent handler.\n  payload        Json?\n  /// Timestamp of the last run.\n  lastRunAt      DateTime?\n  /// Next scheduled run timestamp (computed from cron expression).\n  nextRunAt      DateTime?\n  /// Creation timestamp.\n  createdAt      DateTime     @default(now())\n  /// Update timestamp.\n  updatedAt      DateTime     @updatedAt\n\n  @@index([organizationId])\n  @@index([nextRunAt, isEnabled])\n  @@map(\"task\")\n}\n",
